"""Run the production render command with the repository's actual manifest."""
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest

REPOSITORY_ROOT = Path(__file__).resolve().parents[4]

class BundleRenderCommandTest(unittest.TestCase):
    # Generated by Codex and not thoroughly checked for correctness.
    def test_writes_image_only_release_compose_from_production_manifest(self):
        with tempfile.TemporaryDirectory(prefix="cftracker-compose-test-") as directory:
            subprocess.run([
                sys.executable,
                str(REPOSITORY_ROOT / "backend/deploy/vps/bundle_helpers.py"),
                "render-compose", str(REPOSITORY_ROOT), directory, "release-001",
            ], check=True, capture_output=True, text=True)

            rendered = (Path(directory) / "compose.yml").read_text()
            self.assertNotIn("    build:", rendered)
            self.assertIn("image: cftracker-backend:release-001", rendered)
            self.assertIn("image: cftracker-migration:release-001", rendered)
            self.assertEqual(rendered.count("    pull_policy: never"), 2)
            self.assertIn("/etc/cftracker/init-app-role.sql:", rendered)
            self.assertIn('127.0.0.1:8080:8080', rendered)
            self.assertIn('    env_file: ["/etc/cftracker/migration.env"]', rendered)
